<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { listPublications,type PublicationSummary } from '../api/references'
const rows=ref<PublicationSummary[]>([]),page=ref(1),total=ref(0),q=ref(''),loading=ref(false),error=ref('');let generation=0
async function load(reset=false){if(reset)page.value=1;const current=++generation;loading.value=true;error.value='';try{const result=await listPublications(page.value,q.value);if(current===generation){rows.value=result.items;total.value=result.total}}catch(failure){if(current===generation)error.value=failure instanceof Error?failure.message:'读取失败'}finally{if(current===generation)loading.value=false}}
onMounted(()=>load())
</script>
<template><section class="panel"><div class="list-filters"><el-input v-model="q" aria-label="搜索发布标题" placeholder="搜索发布标题" @keyup.enter="load(true)" /><el-button @click="load(true)">查询</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-table v-loading="loading" :data="rows" empty-text="暂无已发布稿件"><el-table-column label="已发布标题" min-width="250"><template #default="{row}"><RouterLink :to="`/publications/${row.manuscriptId}`">{{ row.title }}</RouterLink></template></el-table-column><el-table-column prop="organizationName" label="投稿组织" width="200" /><el-table-column label="发布时间" width="200"><template #default="{row}">{{ new Date(row.publishedAt).toLocaleString('zh-CN') }}</template></el-table-column></el-table><el-pagination v-if="total>20" v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next, total" @current-change="load()" /></section></template>
